+    (mask.charCodeAt(7) | 0x20 === 0x6e) && // 'n'
+    (mask.charCodeAt(8) | 0x20 === 0x64) && // 'd'
+    (mask.charCodeAt(9) | 0x20 === 0x61) && // 'a'
+    (mask.charCodeAt(10) | 0x20 === 0x72) && // 'r'
+    (mask.charCodeAt(11) | 0x20 === 0x64) // 'd
+  )
+}
